{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.04,
  "summary": [
    "Forecasts consistently show CDU or Greens ahead of AfD in Baden-Württemberg, with AfD around high-teens to ~20%.",
    "Historical base-rate in BW strongly disfavors AfD leading the largest share of seats; Thuringia in 2024 is an outlier.",
    "Coalition norms and the explicit 'firewall' against AfD governance further reduce chances of AfD becoming the largest party.",
    "Unforeseen turnout shocks could marginally lift AfD, but are unlikely to flip the plurality."
  ],
  "confidence": "high",
  "narrative": "Based on the reference-class evidence and current polling, AfD winning the most seats in Baden-Württemberg is essentially zero. The combined impact of polls showing AfD well behind top two parties and the long-standing BW pattern, plus coalition norms, yields a near-zero calibrated probability with only a small tail-risk upside from turnout shocks.",
  "justification": {
    "anchor": {
      "probability": 0.02,
      "basis": "reference_class and anchor probability chosen to reflect the consistent historical pattern in Baden-Württemberg that AfD has not held the most seats; base-rate anchor anchored near the low two-percent range to reflect the rarity of the outcome."
    },
    "factor_updates": [
      {
        "factor": "Polls showing AfD far behind the top two (CDU/Greens) and only in high-teens to ~20%",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Multiple credible polls place AfD well behind CDU/Greens, making a plurality for AfD unlikely and depressing the probability of being the largest party."
      },
      {
        "factor": "Main parties' explicit anti-AfD coalitional stance (firewall) and aversion to AfD-led governance",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Even if AfD accrues votes, mainstream parties' reluctance to govern with or be led by AfD reduces the practical likelihood of AfD achieving top-status."
      },
      {
        "factor": "Historical Baden-Württemberg base-rate (AfD never led BW; Thuringia 2024 is an outlier)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "BW has a long pattern of CDU/Greens ahead; the outlier Thuringia does not transfer to BW dynamics."
      },
      {
        "factor": "Unforeseen turnout swings or issue-driven shocks that could boost AfD",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Possible but unlikely to yield a sustained plurality; any uplift is expected to be small and not sufficient to overcome the baseline gap."
      }
    ],
    "synthesis_rationale": "The synthesis weights the persistent polling gaps and entrenched BW historical patterns far more than transient shocks. The baseline anchor is near-zero, and even modest positive shocks are insufficient to overcome the structural disadvantages, resulting in a calibrated probability at the near-zero end with a small range to reflect tail risk."
  }
}

